def load_bed_intervals(path):
    d=defaultdict(list)
    if not path: return d
    f=open_text(path)
    if f is None: return d
    with f:
        for line in f:
            if not line.strip() or line.startswith('#'): continue
            t=line.rstrip('\n').split('\t')
            if len(t)==1: t=line.split()
            if not t: continue
            name=t[0]
            if len(t)>=3 and t[1] and t[1][0].isdigit():
                try: b=int(t[1]); e=int(t[2]); strand=t[5] if len(t)>5 else '+'
                except: continue
                d[name].append((b,e,strand))
            elif len(t)>=2 and t[1] and t[1][0].isdigit():
                try: p=int(t[1])-1; d[name].append((p,p+1,'+'))
                except: pass
            else:
                d[name].append((None,None,'+'))
    return d

def apply_mask_intervals(name, seq, intervals, complement=False):
    marks=[False]*len(seq)
    for b,e,st in intervals.get(name,[]):
        if b is None:
            b=0; e=len(seq)
        b=max(0,b); e=min(len(seq),e)
        for i in range(b,e): marks[i]=True
    if complement:
        marks=[not x for x in marks]
    return ''.join(ch.lower() if marks[i] else ch for i,ch in enumerate(seq))

def cmd_size(argv):
    path=argv[0] if argv else None
    it=rec_iter_or_error(path,'stk_size')
    if it is None: return 1
    n=0; b=0
    for r in it:
        n+=1; b+=len(r.seq)
    print(f"{n}\t{b}")
    return 0

def cmd_comp(argv):
    path=argv[0] if argv else None
    it=read_records(path)
    if it is None: return 0
    two=set('RYSWKMryswkm'); three=set('BDHVbdhv')
    for r in it:
        seq=r.seq
        A=sum(1 for c in seq if c in 'Aa')
        C=sum(1 for c in seq if c in 'Cc')
        G=sum(1 for c in seq if c in 'Gg')
        T=sum(1 for c in seq if c in 'Tt')
        H2=sum(1 for c in seq if c in two)
        H3=sum(1 for c in seq if c in three)
        N=sum(1 for c in seq if c in 'Nn')
        cpg=0
        up=seq.upper()
        for i in range(len(up)-1):
            if up[i:i+2]=='CG': cpg += 2
        tv=sum(1 for c in seq if c in 'SWKMswkm')
        ts=sum(1 for c in seq if c in 'RYry')
        print(f"{r.name}\t{len(seq)}\t{A}\t{C}\t{G}\t{T}\t{H2}\t{H3}\t{N}\t{cpg}\t{tv}\t{ts}\t0")
    return 0

def usage_subseq():
    print("Usage:   seqtk subseq [options] <in.fa> <in.bed>|<name.list>\nOptions:\n  -t       TAB delimited output\n  -s       strand aware\n  -l INT   sequence line length [0]\nNote: Use 'samtools faidx' if only a few regions are intended.", file=sys.stderr)

def cmd_subseq(argv):
    opts,rest=parse_opts(argv,set('l'),set('ts'),'subseq')
    tab=False; strand=False; line_len=0
    for c,v in opts:
        if c=='t': tab=True
        elif c=='s': strand=True
        elif c=='l':
            try: line_len=int(v)
            except: line_len=0
    if len(rest)<2:
        usage_subseq(); return 1
    inpath, listpath=rest[0], rest[1]
    lines=[]
    try:
        with open_text(listpath) as f:
            for line in f:
                if line.strip() and not line.startswith('#'):
                    lines.append(line.rstrip('\n'))
    except Exception:
        usage_subseq(); return 1
    is_bed=any(len(x.split())>=2 for x in lines)
    names=set(); regs=defaultdict(list)
    if is_bed:
        for line in lines:
            t=line.split()
            if not t: continue
            name=t[0]
            if len(t)>=3 and t[1][0].isdigit():
                try: b=int(t[1]); e=int(t[2]); st=t[5] if len(t)>5 else '+'
                except: continue
                regs[name].append((b,e,st,False))
            elif len(t)>=2 and t[1][0].isdigit():
                try: p=int(t[1])-1; regs[name].append((p,p+1,'+',False))
                except: regs[name].append((0,None,'+',True))
            else:
                regs[name].append((0,None,'+',True))
    else:
        names={line.split()[0] for line in lines if line.split()}
    it=read_records(inpath)
    if it is None: return 0
    for r in it:
        if is_bed:
            if r.name not in regs: continue
            for b,e,st,full in regs[r.name]:
                if full or e is None:
                    b=0; e=len(r.seq); nm=r.name
                else:
                    b=max(0,b); e=min(len(r.seq),e); nm=f"{r.name}:{b+1}-{e}"
                if b>=len(r.seq) or e<=b: continue
                seq=r.seq[b:e]; qual=r.qual[b:e] if r.qual is not None else None
                if strand and st=='-':
                    seq=revcomp(seq)
                    if qual is not None: qual=qual[::-1]
                if tab:
                    print(f"{r.name}\t{b+1}\t{seq}")
                elif r.is_fastq:
                    if strand:
                        # Matches observed seqtk behavior for -s on FASTQ: sequence-only records with @ headers.
                        sys.stdout.write(header('@', r, nm, True)); sys.stdout.write(wrap(seq,line_len))
                    else:
                        write_fastq(r,seq,qual,nm,True,line_len)
                else:
                    write_fasta(r,seq,nm,True,line_len)
        else:
            if r.name in names:
                if tab:
                    print(f"{r.name}\t1\t{r.seq}")
                elif r.is_fastq: write_fastq(r,line_len=line_len)
                else: write_fasta(r,line_len=line_len)
    return 0

def usage_sample():
    print("\nUsage:   seqtk sample [-2] [-s seed=11] <in.fa> <frac>|<number>\n\nOptions: -s INT       RNG seed [11]\n         -2           2-pass mode: twice as slow but with much reduced memory\n", file=sys.stderr)

def cmd_sample(argv):
    opts,rest=parse_opts(argv,set('s'),set('2'),'sample')
    seed=11; two=False
    for c,v in opts:
        if c=='s':
            try: seed=int(v)
            except: seed=11
        elif c=='2': two=True
    if len(rest)<2:
        usage_sample(); return 1
    path, target=rest[0], rest[1]
    try:
        frac = float(target)
    except:
        frac=0.0
    is_fraction = ('.' in target or 'e' in target.lower()) and frac < 1.0
    it=read_records(path)
    if it is None: return 1
    recs=list(it)
    rng=random.Random(seed)
    if is_fraction:
        if two:
            print("[W::stk_sample] when sampling a fraction, option -2 is ignored.", file=sys.stderr)
        for r in recs:
            if rng.random() < frac:
                write_fastq(r) if r.is_fastq else write_fasta(r)
    else:
        try: k=int(float(target))
        except: k=0
        if k<=0: return 0
        if k>len(recs): k=len(recs)
        if two:
            # 2-pass prints in input order; reservoir-like deterministic selection
            idx=set(rng.sample(range(len(recs)), k))
            for i,r in enumerate(recs):
                if i in idx: write_fastq(r) if r.is_fastq else write_fasta(r)
        else:
            for r in rng.sample(recs, k):
                write_fastq(r) if r.is_fastq else write_fasta(r)
    return 0

def usage_trimfq():
    print("\nUsage:   seqtk trimfq [options] <in.fq>\n\nOptions: -q FLOAT    error rate threshold (disabled by -b/-e) [0.05]\n         -l INT      maximally trim down to INT bp (disabled by -b/-e) [30]\n         -b INT      trim INT bp from left (non-zero to disable -q/-l) [0]\n         -e INT      trim INT bp from right (non-zero to disable -q/-l) [0]\n         -L INT      retain at most INT bp from the 5'-end (non-zero to disable -q/-l) [0]\n         -Q          force FASTQ output\n", file=sys.stderr, end='')

def cmd_trimfq(argv):
    opts,rest=parse_opts(argv,set('qlbeL'),set(), 'trimfq')  # deliberately leaves -Q invalid, as observed
    qerr=0.05; min_l=30; btrim=0; etrim=0; maxL=0
    for c,v in opts:
        try:
            if c=='q': qerr=float(v)
            elif c=='l': min_l=int(v)
            elif c=='b': btrim=int(v)
            elif c=='e': etrim=int(v)
            elif c=='L': maxL=int(v)
        except: pass
    if len(rest)<1:
        usage_trimfq(); return 1
    it=read_records(rest[0])
    if it is None: return 1
    for r in it:
        seq=r.seq; qual=r.qual
        if r.is_fastq and qual is not None:
            if btrim or etrim or maxL:
                start=min(max(btrim,0),len(seq))
                end=len(seq)-max(etrim,0)
                if maxL and start+maxL < end: end=start+maxL
                if end<start: end=start
            else:
                start,end = phred_trim(qual, qerr, min_l)
            seq=seq[start:end]; qual=qual[start:end]
            write_fastq(r,seq,qual)
        else:
            # FASTA passes through, with fixed clipping if requested
            start=min(max(btrim,0),len(seq)); end=len(seq)-max(etrim,0)
            if maxL and start+maxL<end: end=start+maxL
            if end<start: end=start
            write_fasta(r,seq[start:end])
    return 0

def phred_trim(qual, qerr, min_l):
    n=len(qual)
    if n <= min_l:
        return 0,n
    cutoff = int(-10.0*math.log10(qerr) + .499)
    # BWA/seqtk-style modified Mott trimming from both ends.
    best=0; s=0; left=0
    for i,ch in enumerate(qual):
        s += cutoff - (ord(ch)-33)
        if s < 0: s=0
        elif s > best: best=s; left=i+1
    best=0; s=0; right=n
    for j in range(n-1,-1,-1):
        s += cutoff - (ord(qual[j])-33)
        if s < 0: s=0
        elif s > best: best=s; right=j
    if right-left < min_l:
        # choose the better side-only trim, preserving at least min_l
        if left>n-right:
            right=n
        else:
            left=0
        if right-left < min_l:
            right=min(n,left+min_l)
    return left,right

def usage_fqchk():
    print("Usage: seqtk fqchk [-q 20] <in.fq>\nNote: use -q0 to get the distribution of all quality values", file=sys.stderr)

def cmd_fqchk(argv):
    opts,rest=parse_opts(argv,set('q'),set(),'fqchk')
    qth=20
    for c,v in opts:
        if c=='q':
            try: qth=int(v)
            except: qth=20
    if len(rest)<1:
        usage_fqchk(); return 1
    it=read_records(rest[0])
    if it is None: return 1
    rows=[]; min_len=None; max_len=0; total_len=0; nseq=0; qvals=set()
    for r in it:
        if not r.is_fastq: continue
        nseq+=1; l=len(r.seq); total_len+=l; min_len=l if min_len is None or l<min_len else min_len; max_len=max(max_len,l)
        rows.append((r.seq,r.qual or ''))
        qvals.update(ord(c)-33 for c in (r.qual or ''))
    if nseq==0: return 0
    print(f"min_len: {min_len}; max_len: {max_len}; avg_len: {total_len/nseq:.2f}; {len(qvals)} distinct quality values")
    qlist=sorted(qvals)
    if qth==0:
        print("POS\t#bases\t%A\t%C\t%G\t%T\t%N\tavgQ\terrQ" + ''.join(f"\t%Q{q}" for q in qlist))
    else:
        print("POS\t#bases\t%A\t%C\t%G\t%T\t%N\tavgQ\terrQ\t%low\t%high")
    def calc(pos):
        bases=[]; qs=[]
        if pos is None:
            for s,q in rows:
                bases.extend(s); qs.extend(ord(c)-33 for c in q)
        else:
            for s,q in rows:
                if pos < len(s):
                    bases.append(s[pos]); qs.append(ord(q[pos])-33 if pos < len(q) else 0)
        return bases,qs
    for label,pos in [('ALL',None)] + [(str(i+1),i) for i in range(max_len)]:
        bases,qs=calc(pos)
        if not bases: continue
        nb=len(bases); up=[b.upper() for b in bases]
        pct=lambda x: 100.0*x/nb
        counts=[up.count('A'),up.count('C'),up.count('G'),up.count('T')]
        ncnt=nb-sum(counts)
        avg=sum(qs)/nb if nb else 0
        # error-quality from mean error probability
        ep=sum(10**(-q/10.0) for q in qs)/nb if nb else 1
        errQ=-10*math.log10(ep) if ep>0 else 99
        prefix=f"{label}\t{nb}\t" + '\t'.join(f"{pct(c):.1f}" for c in counts+[ncnt]) + f"\t{avg:.1f}\t{errQ:.1f}"
        if qth==0:
            vals=[sum(1 for q in qs if q==qq) for qq in qlist]
            print(prefix + ''.join(f"\t{pct(v):.2f}" for v in vals))
        else:
            low=sum(1 for q in qs if q<qth); high=nb-low
            print(prefix + f"\t{pct(low):.1f}\t{pct(high):.1f}")
    return 0

def cmd_mergepe(argv):
    if len(argv)<2:
        print("Usage: seqtk mergepe <in1.fq> <in2.fq>", file=sys.stderr); return 1
    it1=read_records(argv[0]); it2=read_records(argv[1])
    if it1 is None or it2 is None: return 1
    while True:
        try: r1=next(it1)
        except StopIteration: r1=None
        try: r2=next(it2)
        except StopIteration: r2=None
        if r1 is None and r2 is None: break
        for r in (r1,r2):
            if r is not None:
                write_fastq(r) if r.is_fastq else write_fasta(r)
    return 0

def cmd_dropse(argv):
    path=argv[0] if argv else None
    it=rec_iter_or_error(path,'stk_dropse')
    if it is None: return 1
    prev=None
    for r in it:
        if prev is None:
            prev=r; continue
        if base_id_for_pair(prev.name)==base_id_for_pair(r.name) and ((is_first(prev.name) and is_second(r.name)) or (is_second(prev.name) and is_first(r.name))):
            for x in (prev,r): write_fastq(x) if x.is_fastq else write_fasta(x)
            prev=None
        else:
            prev=r
    return 0

def usage_split():
    print("Usage: seqtk split [options] <prefix> <in.fa>\nOptions:\n  -n INT    number of files [10]\n  -l INT    line length [0]", file=sys.stderr)

def cmd_split(argv):
    opts,rest=parse_opts(argv,set('nl'),set(),'split')
    n=10; l=0
    for c,v in opts:
        try:
            if c=='n': n=int(v)
            elif c=='l': l=int(v)
        except: pass
    if len(rest)<2:
        usage_split(); return 1
    prefix,path=rest[0],rest[1]
    recs=list(read_records(path) or [])
    if not recs: return 0
    ext='fq' if recs[0].is_fastq else 'fa'
    outs=[]
    for i in range(n): outs.append(open(f"{prefix}.{i+1:05d}.{ext}",'w',encoding='latin1'))
    try:
        for i,r in enumerate(recs):
            out=outs[i%n]
            if r.is_fastq: write_fastq(r,line_len=l,out=out)
            else: write_fasta(r,line_len=l,out=out)
    finally:
        for o in outs: o.close()
