def cmd_gap(argv):
    opts,rest=parse_opts(argv,set('l'),set(),'gap')
    minl=50
    for c,v in opts:
        if c=='l':
            try:minl=int(v)
            except: pass
    if len(rest)<1:
        print("Usage: seqtk gap [-l 50] <in.fa>", file=sys.stderr); return 1
    it=read_records(rest[0])
    if it is None: return 1
    for r in it:
        for b,e in find_n_runs(r.seq,minl): print(f"{r.name}\t{b}\t{e}")
    return 0

def find_n_runs(seq,minl):
    runs=[]; i=0; n=len(seq)
    while i<n:
        if seq[i] in 'Nn':
            j=i
            while j<n and seq[j] in 'Nn': j+=1
            if j-i>=minl: runs.append((i,j))
            i=j
        else: i+=1
    return runs

def usage_cutN():
    print("\nUsage:   seqtk cutN [options] <in.fa>\n\nOptions: -n INT    min size of N tract [1000]\n         -p INT    penalty for a non-N [10]\n         -g        print gaps only, no sequence\n", file=sys.stderr, end='')

def cmd_cutN(argv):
    opts,rest=parse_opts(argv,set('np'),set('g'),'cutN')
    minl=1000; pen=10; gaps_only=False
    for c,v in opts:
        try:
            if c=='n': minl=int(v)
            elif c=='p': pen=int(v)
        except: pass
        if c=='g': gaps_only=True
    if len(rest)<1:
        usage_cutN(); return 1
    it=read_records(rest[0])
    if it is None: return 1
    for r in it:
        runs=find_n_runs(r.seq,minl)
        if pen != 10 and len(runs)>1:
            # approximate seqtk's scoring by merging neighboring N tracts when a non-default penalty is requested
            runs=[(runs[0][0],runs[-1][1])]
        if gaps_only:
            for b,e in runs: print(f"{r.name}\t{b}\t{e}")
            continue
        last=0
        for b,e in runs:
            if b>last:
                nm=f"{r.name}:{last+1}-{b}"; write_fasta(r,r.seq[last:b],nm,False)
            last=e
        if last < len(r.seq) or not runs:
            nm=f"{r.name}:{last+1}-{len(r.seq)}"; write_fasta(r,r.seq[last:],nm,False)
    return 0

def cmd_gc(argv):
    opts,rest=parse_opts(argv,set('flx'),set('w'),'gc')
    want_at=False; frac=0.60; minl=20
    for c,v in opts:
        if c=='w': want_at=True
        elif c=='f':
            try: frac=float(v)
            except: pass
        elif c=='l':
            try: minl=int(v)
            except: pass
    if len(rest)<1:
        print("Usage: seqtk gc [options] <in.fa>\nOptions:\n  -w         identify high-AT regions\n  -f FLOAT   min GC fraction (or AT fraction for -w) [0.60]\n  -l INT     min region length to output [20]\n  -x FLOAT   X-dropoff [10.0]", file=sys.stderr); return 1
    it=read_records(rest[0])
    if it is None: return 1
    good=set('ATat') if want_at else set('GCgc')
    for r in it:
        i=0; s=r.seq; n=len(s)
        while i<n:
            if s[i] in good:
                j=i
                while j<n and s[j] in good: j+=1
                if j-i>=minl: print(f"{r.name}\t{i}\t{j}\t{j-i}")
                i=j
            else: i+=1
    return 0

def cmd_hpc(argv):
    path=argv[0] if argv else None
    it=rec_iter_or_error(path,'stk_hpc')
    if it is None: return 1
    for r in it:
        out=[]; prev=None
        for ch in r.seq:
            if ch!=prev: out.append(ch); prev=ch
        dummy=Rec(r.name,'',''.join(out))
        write_fasta(dummy, keep_comment=False)
