def cmd_rename(argv):
    path=argv[0] if argv else None
    prefix=argv[1] if len(argv)>1 else ''
    it=rec_iter_or_error(path,'stk_rename')
    if it is None: return 1
    last_comment=''
    for i,r in enumerate(it,1):
        # observed bug: previous non-empty comment is reused for commentless records
        if r.comment: last_comment=r.comment
        rr=Rec(str(prefix)+str(i), last_comment, r.seq, r.qual, r.is_fastq)
        write_fastq(rr) if r.is_fastq else write_fasta(rr)
    return 0

IUPAC = {
    frozenset('A'):'A', frozenset('C'):'C', frozenset('G'):'G', frozenset('T'):'T',
    frozenset('AG'):'R', frozenset('CT'):'Y', frozenset('CG'):'S', frozenset('AT'):'W', frozenset('GT'):'K', frozenset('AC'):'M',
    frozenset('CGT'):'B', frozenset('AGT'):'D', frozenset('ACT'):'H', frozenset('ACG'):'V', frozenset('ACGT'):'N'
}
BASESET = {'A':set('A'),'C':set('C'),'G':set('G'),'T':set('T'),'R':set('AG'),'Y':set('CT'),'S':set('CG'),'W':set('AT'),'K':set('GT'),'M':set('AC'),'B':set('CGT'),'D':set('AGT'),'H':set('ACT'),'V':set('ACG'),'N':set('ACGT')}

def cmd_listhet(argv):
    if len(argv)<1:
        print("Usage: seqtk listhet <in.fa>", file=sys.stderr); return 1
    it=read_records(argv[0])
    if it is None: return 1
    for r in it:
        for i,ch in enumerate(r.seq,1):
            if ch in 'RYSWKMr yswkm'.replace(' ',''):
                print(f"{r.name}\t{i}\t{ch}")
    return 0

def cmd_randbase(argv):
    if len(argv)<1:
        print("Usage: seqtk randbase <in.fa>", file=sys.stderr); return 1
    rng=random.Random(11)
    choices={'R':'AG','Y':'CT','S':'CG','W':'AT','K':'GT','M':'AC','r':'ag','y':'ct','s':'cg','w':'at','k':'gt','m':'ac'}
    it=read_records(argv[0])
    if it is None: return 1
    for r in it:
        seq=''.join((rng.choice(choices[ch]) if ch in choices else ch) for ch in r.seq)
        write_fasta(r,seq)
    return 0

def cmd_mutfa(argv):
    if len(argv)<2:
        print("Usage: seqtk mutfa <in.fa> <in.snp>\n\nNote: <in.snp> contains at least four columns per line which are:\n      'chr  1-based-pos  any  base-changed-to'.", file=sys.stderr); return 1
    muts=defaultdict(dict)
    try:
        with open_text(argv[1]) as f:
            for line in f:
                t=line.split()
                if len(t)>=4:
                    try: muts[t[0]][int(t[1])-1]=t[3][0]
                    except: pass
    except: pass
    it=read_records(argv[0])
    if it is None: return 1
    for r in it:
        s=list(r.seq)
        for p,b in muts.get(r.name,{}).items():
            if 0<=p<len(s): s[p]=b
        write_fasta(r,''.join(s))
    return 0

def usage_mergefa():
    print("\nUsage: seqtk mergefa [options] <in1.fa> <in2.fa>\n\nOptions: -q INT   quality threshold [0]\n         -i       take intersection\n         -m       convert to lowercase when one of the input base is N\n         -r       pick a random allele from het\n         -h       suppress hets in the input\n", file=sys.stderr, end='')

def cmd_mergefa(argv):
    opts,rest=parse_opts(argv,set('q'),set('imrh'),'mergefa')
    inter=False; lowerN=False; randhet=False; suppress=False
    for c,v in opts:
        if c=='i': inter=True
        elif c=='m': lowerN=True
        elif c=='r': randhet=True
        elif c=='h': suppress=True
    if len(rest)<2:
        usage_mergefa(); return 1
    recs2={r.name:r for r in (read_records(rest[1]) or [])}
    same=diff=homhet=hethom=hethet=0
    rng=random.Random(11)
    for r1 in (read_records(rest[0]) or []):
        r2=recs2.get(r1.name)
        if not r2: continue
        out=[]
        for a,b in zip(r1.seq,r2.seq):
            A=a.upper(); B=b.upper()
            if A==B and A not in 'N':
                if A in 'RYSWKMBDHV': hethet += 1
                else: same += 1
                ch=A
            elif A=='N' or B=='N':
                other = B if A=='N' else A
                if inter: ch=other
                elif lowerN: ch=other.lower()
                else: ch='N'
            else:
                sa=BASESET.get(A,set('ACGT')); sb=BASESET.get(B,set('ACGT'))
                if len(sa)==1 and len(sb)==1: diff += 1
                elif len(sa)==1: homhet += 1
                elif len(sb)==1: hethom += 1
                else: hethet += 1
                ch=IUPAC.get(frozenset(sa|sb),'N')
            if suppress and ch in 'RYSWKMBDHV': ch=ch.lower()
            if randhet and ch in BASESET and len(BASESET[ch])>1:
                ch=rng.choice(sorted(BASESET[ch]))
            out.append(ch)
        write_fasta(r1,''.join(out))
    print(f"[stk_mergefa] (same,diff,hom-het,het-hom,het-het)=({same},{diff},{homhet},{hethom},{hethet})", file=sys.stderr)
    return 0

def cmd_famask(argv):
    if len(argv)<2:
        print("Usage: seqtk famask <src.fa> <mask.fa>", file=sys.stderr); return 1
    masks={r.name:r.seq for r in (read_records(argv[1]) or [])}
    for r in (read_records(argv[0]) or []):
        m=masks.get(r.name,'')
        out=[]
        for i,ch in enumerate(r.seq):
            mc=m[i] if i<len(m) else 'N'
            if mc == '-': out.append('-')
            elif mc == 'x': out.append(ch.lower())
            elif mc == 'X': out.append(ch.upper())
            else: out.append(ch)
        write_fasta(r,''.join(out))
    return 0

def usage_hety():
    print("\nUsage:   seqtk hety [options] <in.fa>\n\nOptions: -w INT   window size [50000]\n         -t INT   # start positions in a window [5]\n         -m       treat lowercases as masked\n", file=sys.stderr, end='')

def cmd_hety(argv):
    opts,rest=parse_opts(argv,set('wt'),set('m'),'hety')
    if len(rest)<1:
        usage_hety(); return 1
    # Lightweight approximation: report per-window heterozygous two-base code counts.
