def cmd_telo(argv):
    path=argv[0] if argv else None
    total=0; nreg=0
    it=read_records(path)
    if it is not None:
        for r in it: total += len(r.seq)
    print(f"{nreg}\t{total}", file=sys.stderr)
    return 0

COMMANDS = {
    'seq':cmd_seq, 'size':cmd_size, 'comp':cmd_comp, 'subseq':cmd_subseq, 'sample':cmd_sample,
    'trimfq':cmd_trimfq, 'fqchk':cmd_fqchk, 'mergepe':cmd_mergepe, 'dropse':cmd_dropse,
    'split':cmd_split, 'gap':cmd_gap, 'cutN':cmd_cutN, 'gc':cmd_gc, 'hpc':cmd_hpc,
    'rename':cmd_rename, 'listhet':cmd_listhet, 'randbase':cmd_randbase, 'mutfa':cmd_mutfa,
    'mergefa':cmd_mergefa, 'famask':cmd_famask, 'hety':cmd_hety, 'telo':cmd_telo,
}

def main(argv):
    if len(argv)<2:
        cmd_main_usage(); return 1
    cmd=argv[1]
    if cmd not in COMMANDS:
        print(f"[main] unrecognized command '{cmd}'. Abort!", file=sys.stderr); return 1
    return COMMANDS[cmd](argv[2:])

if __name__ == '__main__':
    sys.exit(main(sys.argv))
