#!/usr/bin/env python3
import sys, os, gzip, math, random
from collections import defaultdict, Counter

VERSION = "1.5-r133"

# ---------- basic FASTA/FASTQ IO ----------
class Rec:
    __slots__ = ("name","comment","seq","qual","is_fastq")
    def __init__(self, name, comment, seq, qual=None, is_fastq=False):
        self.name=name; self.comment=comment; self.seq=seq; self.qual=qual; self.is_fastq=is_fastq

def open_text(path):
    if path is None or path == '-':
        return sys.stdin
    try:
        if path.endswith('.gz'):
            return gzip.open(path, 'rt', encoding='latin1', newline=None)
        return open(path, 'rt', encoding='latin1', newline=None)
    except OSError:
        return None

def split_header(h):
    h = h.rstrip('\r\n')
    if not h: return "", ""
    # h does not include leading >/@
    parts = h.split(None, 1)
    if not parts: return "", ""
    return parts[0], (parts[1] if len(parts)>1 else "")

def read_records(path):
    f = open_text(path)
    if f is None:
        return None
    try:
        # streaming parser with one-line pushback
        pending = None
        while True:
            if pending is not None:
                line = pending; pending = None
            else:
                line = f.readline()
            if not line: break
            if not line.strip():
                continue
            if line[0] not in '>@':
                continue
            marker = line[0]
            name, comment = split_header(line[1:])
            seq_lines=[]
            if marker == '>':
                while True:
                    line = f.readline()
                    if not line:
                        break
                    if line and line[0] in '>@':
                        pending = line
                        break
                    seq_lines.append(line.strip())
                yield Rec(name, comment, ''.join(seq_lines), None, False)
            else:
                # sequence until plus line
                while True:
                    line = f.readline()
                    if not line:
                        break
                    if line.startswith('+'):
                        break
                    seq_lines.append(line.strip())
                seq = ''.join(seq_lines)
                q_lines=[]; qlen=0
                while qlen < len(seq):
                    line = f.readline()
                    if not line:
                        break
                    s=line.rstrip('\r\n')
                    q_lines.append(s); qlen += len(s)
                qual=''.join(q_lines)[:len(seq)]
                yield Rec(name, comment, seq, qual, True)
    finally:
        if f is not sys.stdin:
            f.close()

def rec_iter_or_error(path, funcname):
    it = read_records(path)
    if it is None:
        print(f"[E::{funcname}] failed to open the input file/stream.", file=sys.stderr)
        return None
    return it

def header(prefix, rec, name_override=None, comment=True):
    nm = name_override if name_override is not None else rec.name
    if comment and rec.comment:
        return f"{prefix}{nm} {rec.comment}\n"
    return f"{prefix}{nm}\n"

def wrap(s, l=0):
    if l and l > 0:
        return ''.join(s[i:i+l]+'\n' for i in range(0,len(s),l))
    return s + '\n'

def write_fasta(rec, seq=None, name_override=None, keep_comment=True, line_len=0, out=None):
    if out is None: out=sys.stdout
    if seq is None: seq=rec.seq
    out.write(header('>', rec, name_override, keep_comment))
    out.write(wrap(seq, line_len))

def write_fastq(rec, seq=None, qual=None, name_override=None, keep_comment=True, line_len=0, out=None):
    if out is None: out=sys.stdout
    if seq is None: seq=rec.seq
    if qual is None: qual=rec.qual if rec.qual is not None else ''
    out.write(header('@', rec, name_override, keep_comment))
    out.write(wrap(seq, line_len))
    out.write('+\n')
    out.write(wrap(qual, line_len))

_comp = str.maketrans('ACGTRYMKSWBDHVacgtrymkswbdhvnN', 'TGCAYRKMWSVHDBtgcayrkmwsvhdbnN')
def revcomp(s):
    return s.translate(_comp)[::-1]

def base_id_for_pair(name):
    if name.endswith('/1') or name.endswith('/2'):
        return name[:-2]
    if name.endswith('.1') or name.endswith('.2'):
        return name[:-2]
    return name

def is_first(name): return name.endswith('/1') or name.endswith('.1')
def is_second(name): return name.endswith('/2') or name.endswith('.2')

# ---------- option helper ----------
def parse_opts(argv, opt_args, opt_flags, prog, keep_invalid=True):
    opts=[]; rest=[]; i=0
    while i < len(argv):
        a=argv[i]
        if a == '--':
            rest.extend(argv[i+1:]); break
        if not a.startswith('-') or a == '-':
            rest.extend(argv[i:]); break
        j=1
        while j < len(a):
            c=a[j]
            if c in opt_args:
                if j+1 < len(a):
                    val=a[j+1:]; j=len(a)
                else:
                    i += 1
                    val = argv[i] if i < len(argv) else ''
                opts.append((c,val)); break
            elif c in opt_flags:
                opts.append((c,None)); j += 1
            else:
                print(f"{prog}: invalid option -- '{c}'", file=sys.stderr)
                j += 1
        i += 1
    return opts, rest

# ---------- main commands ----------
def cmd_main_usage():
    print(f"\nUsage:   seqtk <command> <arguments>\nVersion: {VERSION}\n\nCommand: seq       common transformation of FASTA/Q\n         size      report the number sequences and bases\n         comp      get the nucleotide composition of FASTA/Q\n         sample    subsample sequences\n         subseq    extract subsequences from FASTA/Q\n         fqchk     fastq QC (base/quality summary)\n         mergepe   interleave two PE FASTA/Q files\n         split     split one file into multiple smaller files\n         trimfq    trim FASTQ using the Phred algorithm\n\n         hety      regional heterozygosity\n         gc        identify high- or low-GC regions\n         mutfa     point mutate FASTA at specified positions\n         mergefa   merge two FASTA/Q files\n         famask    apply a X-coded FASTA to a source FASTA\n         dropse    drop unpaired from interleaved PE FASTA/Q\n         rename    rename sequence names\n         randbase  choose a random base from hets\n         cutN      cut sequence at long N\n         gap       get the gap locations\n         listhet   extract the position of each het\n         hpc       homopolyer-compressed sequence\n         telo      identify telomere repeats in asm or long reads\n", file=sys.stderr, end='')

def cmd_seq(argv):
    opts, rest = parse_opts(argv, set('qXnlQsfMLF'), set('aAcCNr12V'), 'seq')
    force_fa=False; drop_comment=False; line_len=0; qmask=None; qmax=None; qshift=33
    mask_char=None; rev=False; min_len=0; dropN=False; only_odd=False; only_even=False
    frac=1.0; seed=11; fake_qual=None; convert_qual=False; mask_file=None; mask_complement=False
    for c,v in opts:
        if c in 'aA': force_fa=True
        elif c=='C': drop_comment=True
        elif c=='l':
            try: line_len=int(v)
            except: line_len=0
        elif c=='q':
            try: qmask=int(v)
            except: qmask=0
        elif c=='X':
            try: qmax=int(v)
            except: qmax=None
        elif c=='Q':
            try: qshift=int(v)
            except: qshift=33
        elif c=='n': mask_char = v[0] if v else ''
        elif c=='r': rev=True
        elif c=='L':
            try: min_len=int(v)
            except: min_len=0
        elif c=='N': dropN=True
        elif c=='1': only_odd=True
        elif c=='2': only_even=True
        elif c=='f':
            try: frac=float(v)
            except: frac=1.0
        elif c=='s':
            try: seed=int(v)
            except: seed=11
        elif c=='F': fake_qual = (v[0] if v else '')
        elif c=='V': convert_qual=True
        elif c=='M': mask_file=v
        elif c=='c': mask_complement=True
    intervals = load_bed_intervals(mask_file) if mask_file else {}
    rng = random.Random(seed)
    path = rest[0] if rest else None
    it = read_records(path)
    if it is None:
        return 0
    nrec=0
    for rec in it:
        nrec += 1
        if only_odd and (nrec % 2 == 0): continue
        if only_even and (nrec % 2 == 1): continue
        if frac < 1.0 and rng.random() >= frac: continue
        seq=rec.seq
        qual=rec.qual
        if len(seq) < min_len: continue
        if dropN and any(ch not in 'ACGTacgt' for ch in seq): continue
        if intervals:
            seq = apply_mask_intervals(rec.name, seq, intervals, mask_complement)
        if rec.is_fastq and qual is not None:
            if qmask is not None or qmax is not None:
                lst=list(seq)
                for i,ch in enumerate(lst):
                    q = ord(qual[i])-qshift if i < len(qual) else 0
                    bad = (qmask is not None and q < qmask) or (qmax is not None and q > qmax)
                    if bad:
                        lst[i] = mask_char if mask_char is not None else ch.lower()
                seq=''.join(lst)
            if convert_qual:
                qual=''.join(chr(max(0,min(126,ord(ch)-qshift+33))) for ch in qual)
            if fake_qual is not None:
                qual=fake_qual*len(seq)
        elif fake_qual is not None:
            qual=fake_qual*len(seq); rec.is_fastq=True
        if rev:
            seq=revcomp(seq)
            if qual is not None: qual=qual[::-1]
        keep_comment = not drop_comment
        if force_fa or (not rec.is_fastq):
            write_fasta(rec, seq, keep_comment=keep_comment, line_len=line_len)
        else:
            write_fastq(rec, seq, qual, keep_comment=keep_comment, line_len=line_len)
    return 0

def load_bed_intervals(path):
    d=defaultdict(list)
    if not path: return d
    f=open_text(path)
    if f is None: return d
    with f:
        for line in f:
            if not line.strip() or line.startswith('#'): continue
            t=line.rstrip('\n').split('\t')
            if len(t)==1: t=line.split()
            if not t: continue
            name=t[0]
            if len(t)>=3 and t[1] and t[1][0].isdigit():
                try: b=int(t[1]); e=int(t[2]); strand=t[5] if len(t)>5 else '+'
                except: continue
                d[name].append((b,e,strand))
            elif len(t)>=2 and t[1] and t[1][0].isdigit():
                try: p=int(t[1])-1; d[name].append((p,p+1,'+'))
                except: pass
            else:
                d[name].append((None,None,'+'))
    return d

def apply_mask_intervals(name, seq, intervals, complement=False):
    marks=[False]*len(seq)
    for b,e,st in intervals.get(name,[]):
        if b is None:
            b=0; e=len(seq)
        b=max(0,b); e=min(len(seq),e)
        for i in range(b,e): marks[i]=True
    if complement:
        marks=[not x for x in marks]
    return ''.join(ch.lower() if marks[i] else ch for i,ch in enumerate(seq))

def cmd_size(argv):
    path=argv[0] if argv else None
    it=rec_iter_or_error(path,'stk_size')
    if it is None: return 1
    n=0; b=0
    for r in it:
        n+=1; b+=len(r.seq)
    print(f"{n}\t{b}")
    return 0

def cmd_comp(argv):
    path=argv[0] if argv else None
    it=read_records(path)
    if it is None: return 0
    two=set('RYSWKMryswkm'); three=set('BDHVbdhv')
    for r in it:
        seq=r.seq
        A=sum(1 for c in seq if c in 'Aa')
        C=sum(1 for c in seq if c in 'Cc')
        G=sum(1 for c in seq if c in 'Gg')
        T=sum(1 for c in seq if c in 'Tt')
        H2=sum(1 for c in seq if c in two)
        H3=sum(1 for c in seq if c in three)
        N=sum(1 for c in seq if c in 'Nn')
        cpg=0
        up=seq.upper()
        for i in range(len(up)-1):
            if up[i:i+2]=='CG': cpg += 2
        tv=sum(1 for c in seq if c in 'SWKMswkm')
        ts=sum(1 for c in seq if c in 'RYry')
        print(f"{r.name}\t{len(seq)}\t{A}\t{C}\t{G}\t{T}\t{H2}\t{H3}\t{N}\t{cpg}\t{tv}\t{ts}\t0")
    return 0

def usage_subseq():
    print("Usage:   seqtk subseq [options] <in.fa> <in.bed>|<name.list>\nOptions:\n  -t       TAB delimited output\n  -s       strand aware\n  -l INT   sequence line length [0]\nNote: Use 'samtools faidx' if only a few regions are intended.", file=sys.stderr)

def cmd_subseq(argv):
    opts,rest=parse_opts(argv,set('l'),set('ts'),'subseq')
    tab=False; strand=False; line_len=0
    for c,v in opts:
        if c=='t': tab=True
        elif c=='s': strand=True
        elif c=='l':
            try: line_len=int(v)
            except: line_len=0
    if len(rest)<2:
        usage_subseq(); return 1
    inpath, listpath=rest[0], rest[1]
    lines=[]
    try:
        with open_text(listpath) as f:
            for line in f:
                if line.strip() and not line.startswith('#'):
                    lines.append(line.rstrip('\n'))
    except Exception:
        usage_subseq(); return 1
    is_bed=any(len(x.split())>=2 for x in lines)
    names=set(); regs=defaultdict(list)
    if is_bed:
        for line in lines:
            t=line.split()
            if not t: continue
            name=t[0]
            if len(t)>=3 and t[1][0].isdigit():
                try: b=int(t[1]); e=int(t[2]); st=t[5] if len(t)>5 else '+'
                except: continue
                regs[name].append((b,e,st,False))
            elif len(t)>=2 and t[1][0].isdigit():
                try: p=int(t[1])-1; regs[name].append((p,p+1,'+',False))
                except: regs[name].append((0,None,'+',True))
            else:
                regs[name].append((0,None,'+',True))
    else:
        names={line.split()[0] for line in lines if line.split()}
    it=read_records(inpath)
    if it is None: return 0
    for r in it:
        if is_bed:
            if r.name not in regs: continue
            for b,e,st,full in regs[r.name]:
                if full or e is None:
                    b=0; e=len(r.seq); nm=r.name
                else:
                    b=max(0,b); e=min(len(r.seq),e); nm=f"{r.name}:{b+1}-{e}"
                if b>=len(r.seq) or e<=b: continue
                seq=r.seq[b:e]; qual=r.qual[b:e] if r.qual is not None else None
                if strand and st=='-':
                    seq=revcomp(seq)
                    if qual is not None: qual=qual[::-1]
                if tab:
                    print(f"{r.name}\t{b+1}\t{seq}")
                elif r.is_fastq:
                    if strand:
                        # Matches observed seqtk behavior for -s on FASTQ: sequence-only records with @ headers.
                        sys.stdout.write(header('@', r, nm, True)); sys.stdout.write(wrap(seq,line_len))
                    else:
                        write_fastq(r,seq,qual,nm,True,line_len)
                else:
                    write_fasta(r,seq,nm,True,line_len)
        else:
            if r.name in names:
                if tab:
                    print(f"{r.name}\t1\t{r.seq}")
                elif r.is_fastq: write_fastq(r,line_len=line_len)
                else: write_fasta(r,line_len=line_len)
    return 0

def usage_sample():
    print("\nUsage:   seqtk sample [-2] [-s seed=11] <in.fa> <frac>|<number>\n\nOptions: -s INT       RNG seed [11]\n         -2           2-pass mode: twice as slow but with much reduced memory\n", file=sys.stderr)

def cmd_sample(argv):
    opts,rest=parse_opts(argv,set('s'),set('2'),'sample')
    seed=11; two=False
    for c,v in opts:
        if c=='s':
            try: seed=int(v)
            except: seed=11
        elif c=='2': two=True
    if len(rest)<2:
        usage_sample(); return 1
    path, target=rest[0], rest[1]
    try:
        frac = float(target)
    except:
        frac=0.0
    is_fraction = ('.' in target or 'e' in target.lower()) and frac < 1.0
    it=read_records(path)
    if it is None: return 1
    recs=list(it)
    rng=random.Random(seed)
    if is_fraction:
        if two:
            print("[W::stk_sample] when sampling a fraction, option -2 is ignored.", file=sys.stderr)
        for r in recs:
            if rng.random() < frac:
                write_fastq(r) if r.is_fastq else write_fasta(r)
    else:
        try: k=int(float(target))
        except: k=0
        if k<=0: return 0
        if k>len(recs): k=len(recs)
        if two:
            # 2-pass prints in input order; reservoir-like deterministic selection
            idx=set(rng.sample(range(len(recs)), k))
            for i,r in enumerate(recs):
                if i in idx: write_fastq(r) if r.is_fastq else write_fasta(r)
        else:
            for r in rng.sample(recs, k):
                write_fastq(r) if r.is_fastq else write_fasta(r)
    return 0

def usage_trimfq():
    print("\nUsage:   seqtk trimfq [options] <in.fq>\n\nOptions: -q FLOAT    error rate threshold (disabled by -b/-e) [0.05]\n         -l INT      maximally trim down to INT bp (disabled by -b/-e) [30]\n         -b INT      trim INT bp from left (non-zero to disable -q/-l) [0]\n         -e INT      trim INT bp from right (non-zero to disable -q/-l) [0]\n         -L INT      retain at most INT bp from the 5'-end (non-zero to disable -q/-l) [0]\n         -Q          force FASTQ output\n", file=sys.stderr, end='')

def cmd_trimfq(argv):
    opts,rest=parse_opts(argv,set('qlbeL'),set(), 'trimfq')  # deliberately leaves -Q invalid, as observed
    qerr=0.05; min_l=30; btrim=0; etrim=0; maxL=0
    for c,v in opts:
        try:
            if c=='q': qerr=float(v)
            elif c=='l': min_l=int(v)
            elif c=='b': btrim=int(v)
            elif c=='e': etrim=int(v)
            elif c=='L': maxL=int(v)
        except: pass
    if len(rest)<1:
        usage_trimfq(); return 1
    it=read_records(rest[0])
    if it is None: return 1
    for r in it:
        seq=r.seq; qual=r.qual
        if r.is_fastq and qual is not None:
            if btrim or etrim or maxL:
                start=min(max(btrim,0),len(seq))
                end=len(seq)-max(etrim,0)
                if maxL and start+maxL < end: end=start+maxL
                if end<start: end=start
            else:
                start,end = phred_trim(qual, qerr, min_l)
            seq=seq[start:end]; qual=qual[start:end]
            write_fastq(r,seq,qual)
        else:
            # FASTA passes through, with fixed clipping if requested
            start=min(max(btrim,0),len(seq)); end=len(seq)-max(etrim,0)
            if maxL and start+maxL<end: end=start+maxL
            if end<start: end=start
            write_fasta(r,seq[start:end])
    return 0

def phred_trim(qual, qerr, min_l):
    n=len(qual)
    if n <= min_l:
        return 0,n
    cutoff = int(-10.0*math.log10(qerr) + .499)
    # BWA/seqtk-style modified Mott trimming from both ends.
    best=0; s=0; left=0
    for i,ch in enumerate(qual):
        s += cutoff - (ord(ch)-33)
        if s < 0: s=0
        elif s > best: best=s; left=i+1
    best=0; s=0; right=n
    for j in range(n-1,-1,-1):
        s += cutoff - (ord(qual[j])-33)
        if s < 0: s=0
        elif s > best: best=s; right=j
    if right-left < min_l:
        # choose the better side-only trim, preserving at least min_l
        if left>n-right:
            right=n
        else:
            left=0
        if right-left < min_l:
            right=min(n,left+min_l)
    return left,right

def usage_fqchk():
    print("Usage: seqtk fqchk [-q 20] <in.fq>\nNote: use -q0 to get the distribution of all quality values", file=sys.stderr)

def cmd_fqchk(argv):
    opts,rest=parse_opts(argv,set('q'),set(),'fqchk')
    qth=20
    for c,v in opts:
        if c=='q':
            try: qth=int(v)
            except: qth=20
    if len(rest)<1:
        usage_fqchk(); return 1
    it=read_records(rest[0])
    if it is None: return 1
    rows=[]; min_len=None; max_len=0; total_len=0; nseq=0; qvals=set()
    for r in it:
        if not r.is_fastq: continue
        nseq+=1; l=len(r.seq); total_len+=l; min_len=l if min_len is None or l<min_len else min_len; max_len=max(max_len,l)
        rows.append((r.seq,r.qual or ''))
        qvals.update(ord(c)-33 for c in (r.qual or ''))
    if nseq==0: return 0
    print(f"min_len: {min_len}; max_len: {max_len}; avg_len: {total_len/nseq:.2f}; {len(qvals)} distinct quality values")
    qlist=sorted(qvals)
    if qth==0:
        print("POS\t#bases\t%A\t%C\t%G\t%T\t%N\tavgQ\terrQ" + ''.join(f"\t%Q{q}" for q in qlist))
    else:
        print("POS\t#bases\t%A\t%C\t%G\t%T\t%N\tavgQ\terrQ\t%low\t%high")
    def calc(pos):
        bases=[]; qs=[]
        if pos is None:
            for s,q in rows:
                bases.extend(s); qs.extend(ord(c)-33 for c in q)
        else:
            for s,q in rows:
                if pos < len(s):
                    bases.append(s[pos]); qs.append(ord(q[pos])-33 if pos < len(q) else 0)
        return bases,qs
    for label,pos in [('ALL',None)] + [(str(i+1),i) for i in range(max_len)]:
        bases,qs=calc(pos)
        if not bases: continue
        nb=len(bases); up=[b.upper() for b in bases]
        pct=lambda x: 100.0*x/nb
        counts=[up.count('A'),up.count('C'),up.count('G'),up.count('T')]
        ncnt=nb-sum(counts)
        avg=sum(qs)/nb if nb else 0
        # error-quality from mean error probability
        ep=sum(10**(-q/10.0) for q in qs)/nb if nb else 1
        errQ=-10*math.log10(ep) if ep>0 else 99
        prefix=f"{label}\t{nb}\t" + '\t'.join(f"{pct(c):.1f}" for c in counts+[ncnt]) + f"\t{avg:.1f}\t{errQ:.1f}"
        if qth==0:
            vals=[sum(1 for q in qs if q==qq) for qq in qlist]
            print(prefix + ''.join(f"\t{pct(v):.2f}" for v in vals))
        else:
            low=sum(1 for q in qs if q<qth); high=nb-low
            print(prefix + f"\t{pct(low):.1f}\t{pct(high):.1f}")
    return 0

def cmd_mergepe(argv):
    if len(argv)<2:
        print("Usage: seqtk mergepe <in1.fq> <in2.fq>", file=sys.stderr); return 1
    it1=read_records(argv[0]); it2=read_records(argv[1])
    if it1 is None or it2 is None: return 1
    while True:
        try: r1=next(it1)
        except StopIteration: r1=None
        try: r2=next(it2)
        except StopIteration: r2=None
        if r1 is None and r2 is None: break
        for r in (r1,r2):
            if r is not None:
                write_fastq(r) if r.is_fastq else write_fasta(r)
    return 0

def cmd_dropse(argv):
    path=argv[0] if argv else None
    it=rec_iter_or_error(path,'stk_dropse')
    if it is None: return 1
    prev=None
    for r in it:
        if prev is None:
            prev=r; continue
        if base_id_for_pair(prev.name)==base_id_for_pair(r.name) and ((is_first(prev.name) and is_second(r.name)) or (is_second(prev.name) and is_first(r.name))):
            for x in (prev,r): write_fastq(x) if x.is_fastq else write_fasta(x)
            prev=None
        else:
            prev=r
    return 0

def usage_split():
    print("Usage: seqtk split [options] <prefix> <in.fa>\nOptions:\n  -n INT    number of files [10]\n  -l INT    line length [0]", file=sys.stderr)

def cmd_split(argv):
    opts,rest=parse_opts(argv,set('nl'),set(),'split')
    n=10; l=0
    for c,v in opts:
        try:
            if c=='n': n=int(v)
            elif c=='l': l=int(v)
        except: pass
    if len(rest)<2:
        usage_split(); return 1
    prefix,path=rest[0],rest[1]
    recs=list(read_records(path) or [])
    if not recs: return 0
    ext='fq' if recs[0].is_fastq else 'fa'
    outs=[]
    for i in range(n): outs.append(open(f"{prefix}.{i+1:05d}.{ext}",'w',encoding='latin1'))
    try:
        for i,r in enumerate(recs):
            out=outs[i%n]
            if r.is_fastq: write_fastq(r,line_len=l,out=out)
            else: write_fasta(r,line_len=l,out=out)
    finally:
        for o in outs: o.close()
    return 0

def cmd_gap(argv):
    opts,rest=parse_opts(argv,set('l'),set(),'gap')
    minl=50
    for c,v in opts:
        if c=='l':
            try:minl=int(v)
            except: pass
    if len(rest)<1:
        print("Usage: seqtk gap [-l 50] <in.fa>", file=sys.stderr); return 1
    it=read_records(rest[0])
    if it is None: return 1
    for r in it:
        for b,e in find_n_runs(r.seq,minl): print(f"{r.name}\t{b}\t{e}")
    return 0

def find_n_runs(seq,minl):
    runs=[]; i=0; n=len(seq)
    while i<n:
        if seq[i] in 'Nn':
            j=i
            while j<n and seq[j] in 'Nn': j+=1
            if j-i>=minl: runs.append((i,j))
            i=j
        else: i+=1
    return runs

def usage_cutN():
    print("\nUsage:   seqtk cutN [options] <in.fa>\n\nOptions: -n INT    min size of N tract [1000]\n         -p INT    penalty for a non-N [10]\n         -g        print gaps only, no sequence\n", file=sys.stderr, end='')

def cmd_cutN(argv):
    opts,rest=parse_opts(argv,set('np'),set('g'),'cutN')
    minl=1000; pen=10; gaps_only=False
    for c,v in opts:
        try:
            if c=='n': minl=int(v)
            elif c=='p': pen=int(v)
        except: pass
        if c=='g': gaps_only=True
    if len(rest)<1:
        usage_cutN(); return 1
    it=read_records(rest[0])
    if it is None: return 1
    for r in it:
        runs=find_n_runs(r.seq,minl)
        if pen != 10 and len(runs)>1:
            # approximate seqtk's scoring by merging neighboring N tracts when a non-default penalty is requested
            runs=[(runs[0][0],runs[-1][1])]
        if gaps_only:
            for b,e in runs: print(f"{r.name}\t{b}\t{e}")
            continue
        last=0
        for b,e in runs:
            if b>last:
                nm=f"{r.name}:{last+1}-{b}"; write_fasta(r,r.seq[last:b],nm,False)
            last=e
        if last < len(r.seq) or not runs:
            nm=f"{r.name}:{last+1}-{len(r.seq)}"; write_fasta(r,r.seq[last:],nm,False)
    return 0

def cmd_gc(argv):
    opts,rest=parse_opts(argv,set('flx'),set('w'),'gc')
    want_at=False; frac=0.60; minl=20
    for c,v in opts:
        if c=='w': want_at=True
        elif c=='f':
            try: frac=float(v)
            except: pass
        elif c=='l':
            try: minl=int(v)
            except: pass
    if len(rest)<1:
        print("Usage: seqtk gc [options] <in.fa>\nOptions:\n  -w         identify high-AT regions\n  -f FLOAT   min GC fraction (or AT fraction for -w) [0.60]\n  -l INT     min region length to output [20]\n  -x FLOAT   X-dropoff [10.0]", file=sys.stderr); return 1
    it=read_records(rest[0])
    if it is None: return 1
    good=set('ATat') if want_at else set('GCgc')
    for r in it:
        i=0; s=r.seq; n=len(s)
        while i<n:
            if s[i] in good:
                j=i
                while j<n and s[j] in good: j+=1
                if j-i>=minl: print(f"{r.name}\t{i}\t{j}\t{j-i}")
                i=j
            else: i+=1
    return 0

def cmd_hpc(argv):
    path=argv[0] if argv else None
    it=rec_iter_or_error(path,'stk_hpc')
    if it is None: return 1
    for r in it:
        out=[]; prev=None
        for ch in r.seq:
            if ch!=prev: out.append(ch); prev=ch
        dummy=Rec(r.name,'',''.join(out))
        write_fasta(dummy, keep_comment=False)
    return 0

def cmd_rename(argv):
    path=argv[0] if argv else None
    prefix=argv[1] if len(argv)>1 else ''
    it=rec_iter_or_error(path,'stk_rename')
    if it is None: return 1
    last_comment=''
    for i,r in enumerate(it,1):
        # observed bug: previous non-empty comment is reused for commentless records
        if r.comment: last_comment=r.comment
        rr=Rec(str(prefix)+str(i), last_comment, r.seq, r.qual, r.is_fastq)
        write_fastq(rr) if r.is_fastq else write_fasta(rr)
    return 0

IUPAC = {
    frozenset('A'):'A', frozenset('C'):'C', frozenset('G'):'G', frozenset('T'):'T',
    frozenset('AG'):'R', frozenset('CT'):'Y', frozenset('CG'):'S', frozenset('AT'):'W', frozenset('GT'):'K', frozenset('AC'):'M',
    frozenset('CGT'):'B', frozenset('AGT'):'D', frozenset('ACT'):'H', frozenset('ACG'):'V', frozenset('ACGT'):'N'
}
BASESET = {'A':set('A'),'C':set('C'),'G':set('G'),'T':set('T'),'R':set('AG'),'Y':set('CT'),'S':set('CG'),'W':set('AT'),'K':set('GT'),'M':set('AC'),'B':set('CGT'),'D':set('AGT'),'H':set('ACT'),'V':set('ACG'),'N':set('ACGT')}

def cmd_listhet(argv):
    if len(argv)<1:
        print("Usage: seqtk listhet <in.fa>", file=sys.stderr); return 1
    it=read_records(argv[0])
    if it is None: return 1
    for r in it:
        for i,ch in enumerate(r.seq,1):
            if ch in 'RYSWKMr yswkm'.replace(' ',''):
                print(f"{r.name}\t{i}\t{ch}")
    return 0

def cmd_randbase(argv):
    if len(argv)<1:
        print("Usage: seqtk randbase <in.fa>", file=sys.stderr); return 1
    rng=random.Random(11)
    choices={'R':'AG','Y':'CT','S':'CG','W':'AT','K':'GT','M':'AC','r':'ag','y':'ct','s':'cg','w':'at','k':'gt','m':'ac'}
    it=read_records(argv[0])
    if it is None: return 1
    for r in it:
        seq=''.join((rng.choice(choices[ch]) if ch in choices else ch) for ch in r.seq)
        write_fasta(r,seq)
    return 0

def cmd_mutfa(argv):
    if len(argv)<2:
        print("Usage: seqtk mutfa <in.fa> <in.snp>\n\nNote: <in.snp> contains at least four columns per line which are:\n      'chr  1-based-pos  any  base-changed-to'.", file=sys.stderr); return 1
    muts=defaultdict(dict)
    try:
        with open_text(argv[1]) as f:
            for line in f:
                t=line.split()
                if len(t)>=4:
                    try: muts[t[0]][int(t[1])-1]=t[3][0]
                    except: pass
    except: pass
    it=read_records(argv[0])
    if it is None: return 1
    for r in it:
        s=list(r.seq)
        for p,b in muts.get(r.name,{}).items():
            if 0<=p<len(s): s[p]=b
        write_fasta(r,''.join(s))
    return 0

def usage_mergefa():
    print("\nUsage: seqtk mergefa [options] <in1.fa> <in2.fa>\n\nOptions: -q INT   quality threshold [0]\n         -i       take intersection\n         -m       convert to lowercase when one of the input base is N\n         -r       pick a random allele from het\n         -h       suppress hets in the input\n", file=sys.stderr, end='')

def cmd_mergefa(argv):
    opts,rest=parse_opts(argv,set('q'),set('imrh'),'mergefa')
    inter=False; lowerN=False; randhet=False; suppress=False
    for c,v in opts:
        if c=='i': inter=True
        elif c=='m': lowerN=True
        elif c=='r': randhet=True
        elif c=='h': suppress=True
    if len(rest)<2:
        usage_mergefa(); return 1
    recs2={r.name:r for r in (read_records(rest[1]) or [])}
    same=diff=homhet=hethom=hethet=0
    rng=random.Random(11)
    for r1 in (read_records(rest[0]) or []):
        r2=recs2.get(r1.name)
        if not r2: continue
        out=[]
        for a,b in zip(r1.seq,r2.seq):
            A=a.upper(); B=b.upper()
            if A==B and A not in 'N':
                if A in 'RYSWKMBDHV': hethet += 1
                else: same += 1
                ch=A
            elif A=='N' or B=='N':
                other = B if A=='N' else A
                if inter: ch=other
                elif lowerN: ch=other.lower()
                else: ch='N'
            else:
                sa=BASESET.get(A,set('ACGT')); sb=BASESET.get(B,set('ACGT'))
                if len(sa)==1 and len(sb)==1: diff += 1
                elif len(sa)==1: homhet += 1
                elif len(sb)==1: hethom += 1
                else: hethet += 1
                ch=IUPAC.get(frozenset(sa|sb),'N')
            if suppress and ch in 'RYSWKMBDHV': ch=ch.lower()
            if randhet and ch in BASESET and len(BASESET[ch])>1:
                ch=rng.choice(sorted(BASESET[ch]))
            out.append(ch)
        write_fasta(r1,''.join(out))
    print(f"[stk_mergefa] (same,diff,hom-het,het-hom,het-het)=({same},{diff},{homhet},{hethom},{hethet})", file=sys.stderr)
    return 0

def cmd_famask(argv):
    if len(argv)<2:
        print("Usage: seqtk famask <src.fa> <mask.fa>", file=sys.stderr); return 1
    masks={r.name:r.seq for r in (read_records(argv[1]) or [])}
    for r in (read_records(argv[0]) or []):
        m=masks.get(r.name,'')
        out=[]
        for i,ch in enumerate(r.seq):
            mc=m[i] if i<len(m) else 'N'
            if mc == '-': out.append('-')
            elif mc == 'x': out.append(ch.lower())
            elif mc == 'X': out.append(ch.upper())
            else: out.append(ch)
        write_fasta(r,''.join(out))
    return 0

def usage_hety():
    print("\nUsage:   seqtk hety [options] <in.fa>\n\nOptions: -w INT   window size [50000]\n         -t INT   # start positions in a window [5]\n         -m       treat lowercases as masked\n", file=sys.stderr, end='')

def cmd_hety(argv):
    opts,rest=parse_opts(argv,set('wt'),set('m'),'hety')
    if len(rest)<1:
        usage_hety(); return 1
    # Lightweight approximation: report per-window heterozygous two-base code counts.
    w=50000
    for c,v in opts:
        if c=='w':
            try:w=int(v)
            except: pass
    for r in (read_records(rest[0]) or []):
        for b in range(0,len(r.seq),w):
            seg=r.seq[b:b+w]
            h=sum(1 for ch in seg if ch in 'RYSWKMryswkm')
            if h: print(f"{r.name}\t{b}\t{b+len(seg)}\t{h}\t{len(seg)}")
    return 0

def cmd_telo(argv):
    path=argv[0] if argv else None
    total=0; nreg=0
    it=read_records(path)
    if it is not None:
        for r in it: total += len(r.seq)
    print(f"{nreg}\t{total}", file=sys.stderr)
    return 0

COMMANDS = {
    'seq':cmd_seq, 'size':cmd_size, 'comp':cmd_comp, 'subseq':cmd_subseq, 'sample':cmd_sample,
    'trimfq':cmd_trimfq, 'fqchk':cmd_fqchk, 'mergepe':cmd_mergepe, 'dropse':cmd_dropse,
    'split':cmd_split, 'gap':cmd_gap, 'cutN':cmd_cutN, 'gc':cmd_gc, 'hpc':cmd_hpc,
    'rename':cmd_rename, 'listhet':cmd_listhet, 'randbase':cmd_randbase, 'mutfa':cmd_mutfa,
    'mergefa':cmd_mergefa, 'famask':cmd_famask, 'hety':cmd_hety, 'telo':cmd_telo,
}

def main(argv):
    if len(argv)<2:
        cmd_main_usage(); return 1
    cmd=argv[1]
    if cmd not in COMMANDS:
        print(f"[main] unrecognized command '{cmd}'. Abort!", file=sys.stderr); return 1
    return COMMANDS[cmd](argv[2:])

if __name__ == '__main__':
    sys.exit(main(sys.argv))
